def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Determine the starting path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split remaining path into components
    components = remaining.split('/')

    # Track number of links followed
    link_count = 0

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if this path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the target
            target = links[current]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                remaining = target[1:]
            else:
                # Relative target - relative to directory containing the link
                link_dir = current.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                current = link_dir
                remaining = target

            # Split the remaining path and continue
            components = remaining.split('/')

    # Return result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

